package testutil

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// DEVDESK-199: tests build key presses and pick a colour profile through the
// helpers in this package and internal/testutil/colorprofile, never by hand.
// A hand-built tea.KeyMsg{Type: tea.KeyRunes, Runes: ...} drifts from what the
// terminal really sends, and lipgloss.SetColorProfile / termenv leak a global
// across tests. This guard reads every *_test.go the way internal/ui/keymap's
// scans do, and names file:line for each offence.
//
// Using tea.KeyMsg as a TYPE (assertion, parameter, return) stays allowed.

const (
	bubbleteaPath = "github.com/charmbracelet/bubbletea"
	termenvPath   = "github.com/muesli/termenv"
)

// fieldSelectorExceptions lists "<slash path suffix>:<selector>" pairs allowed
// to use .Runes / .Alt / .Paste. Empty on purpose: every entry needs a reason
// written next to it.
var fieldSelectorExceptions = map[string]string{}

var bannedFields = map[string]bool{"Runes": true, "Alt": true, "Paste": true}

// skippedDirs are module-relative slash paths the scan does not enter.
var skippedDirs = []string{"internal/ui/testutil", "internal/testutil/colorprofile"}

// guardSource returns one message per offence in src ("name:line: reason").
func guardSource(fset *token.FileSet, name string, src any) ([]string, error) {
	file, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
	if err != nil {
		return nil, err
	}
	var teaNames []string
	var out []string
	report := func(pos token.Pos, format string, args ...any) {
		out = append(out, fmt.Sprintf("%s: %s", fset.Position(pos), fmt.Sprintf(format, args...)))
	}
	for _, imp := range file.Imports {
		p, _ := strconv.Unquote(imp.Path.Value)
		switch p {
		case bubbleteaPath:
			n := "tea"
			if imp.Name != nil {
				n = imp.Name.Name
			}
			if n != "_" && n != "." {
				teaNames = append(teaNames, n)
			}
		case termenvPath:
			report(imp.Pos(), "imports %s; use internal/testutil/colorprofile", termenvPath)
		}
	}
	isTea := func(e ast.Expr) (string, bool) {
		id, ok := e.(*ast.Ident)
		if !ok {
			return "", false
		}
		for _, n := range teaNames {
			if id.Name == n {
				return n, true
			}
		}
		return "", false
	}
	slash := filepath.ToSlash(name)
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.CompositeLit:
			if sel, ok := x.Type.(*ast.SelectorExpr); ok {
				if pkg, ok := isTea(sel.X); ok && (sel.Sel.Name == "KeyMsg" || sel.Sel.Name == "Key") {
					report(x.Pos(), "composite literal %s.%s; use testutil.Key/Keys/Type", pkg, sel.Sel.Name)
				}
			}
		case *ast.SelectorExpr:
			if pkg, ok := isTea(x.X); ok {
				if strings.HasPrefix(x.Sel.Name, "Key") && x.Sel.Name != "KeyMsg" {
					report(x.Pos(), "%s.%s; use testutil.Key/Keys/Type", pkg, x.Sel.Name)
				}
			} else if id, ok := x.X.(*ast.Ident); ok && id.Name == "testutil" {
				// testutil.Paste is the sanctioned helper, a package-qualified
				// call and not a field of a key message: not an offence.
			} else if bannedFields[x.Sel.Name] {
				allowed := false
				for k := range fieldSelectorExceptions {
					if i := strings.LastIndex(k, ":"); i > 0 && strings.HasSuffix(slash, k[:i]) && k[i+1:] == x.Sel.Name {
						allowed = true
					}
				}
				if !allowed {
					report(x.Sel.Pos(), "selector .%s on a key message; use the testutil helpers", x.Sel.Name)
				}
			}
			if id, ok := x.X.(*ast.Ident); ok && id.Name == "lipgloss" && x.Sel.Name == "SetColorProfile" {
				report(x.Pos(), "lipgloss.SetColorProfile; use internal/testutil/colorprofile")
			}
		}
		return true
	})
	return out, nil
}

func moduleRoot(t *testing.T) string {
	t.Helper()
	dir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatal("go.mod not found above the working directory")
		}
		dir = parent
	}
}

func TestGuardNoHandBuiltKeysOrColorProfile(t *testing.T) {
	root := moduleRoot(t)
	fset := token.NewFileSet()
	var violations []string
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		rel = filepath.ToSlash(rel)
		if d.IsDir() {
			if rel != "." && strings.HasPrefix(d.Name(), ".") {
				return filepath.SkipDir
			}
			for _, s := range skippedDirs {
				if rel == s {
					return filepath.SkipDir
				}
			}
			return nil
		}
		if !strings.HasSuffix(path, "_test.go") {
			return nil
		}
		v, err := guardSource(fset, rel, mustRead(t, path))
		if err != nil {
			t.Errorf("%s: %v", rel, err)
			return nil
		}
		violations = append(violations, v...)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(violations)
	for _, v := range violations {
		t.Errorf("%s", v)
	}
}

func mustRead(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestGuardDetectorSelfTest(t *testing.T) {
	const bad = `package x

import (
	tea "github.com/charmbracelet/bubbletea"
	bt "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/muesli/termenv"
)

func f(m tea.Msg) {
	_ = tea.KeyMsg{Type: tea.KeyEnter}
	_ = bt.Key{}
	_ = bt.KeyCtrlC
	k := m.(tea.KeyMsg)
	_ = k.Runes
	_ = k.Alt
	_ = k.Paste
	lipgloss.SetColorProfile(termenv.Ascii)
}
`
	const good = `package x

import (
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"x/testutil"
)

type other struct{ KeyEnter int }

func f(m tea.Msg, o other) tea.KeyMsg {
	k, _ := m.(tea.KeyMsg)
	_ = o.KeyEnter
	_ = testutil.Paste("x")
	_ = lipgloss.NewStyle()
	return k
}

`
	got, err := guardSource(token.NewFileSet(), "bad_test.go", bad)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"imports " + termenvPath, "composite literal tea.KeyMsg", "tea.KeyEnter",
		"composite literal bt.Key", "bt.KeyCtrlC", ".Runes", ".Alt", ".Paste", "lipgloss.SetColorProfile",
	}
	for _, w := range want {
		found := false
		for _, g := range got {
			if strings.Contains(g, w) {
				found = true
			}
		}
		if !found {
			t.Errorf("detector missed %q; got %q", w, got)
		}
	}
	got, err = guardSource(token.NewFileSet(), "good_test.go", good)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 0 {
		t.Errorf("false positives: %q", got)
	}
}
// Package colorprofile forces a lipgloss colour profile in tests.
//
// Under `go test` lipgloss detects no TTY, falls back to the Ascii profile and
// strips every escape sequence, so an assertion about styling passes whatever
// the code does. Tests that check something is or is not styled (Rule 122) call
// TrueColor first, or Force from TestMain.
//
// This is a leaf package on purpose: it imports only lipgloss and termenv.
// Hosting it in internal/ui/testutil would create an import cycle for the
// packages that testutil itself depends on (testutil -> shortcut -> theme), so
// those packages could not use it from their own tests.
package colorprofile

import (
	"github.com/charmbracelet/lipgloss"
	"github.com/muesli/termenv"
)

// TrueColor forces the TrueColor profile for the length of a test and restores
// the previous profile on Cleanup.
func TrueColor(t interface {
	Helper()
	Cleanup(func())
}) {
	t.Helper()
	t.Cleanup(Force())
}

// Force sets the TrueColor profile and returns a func restoring the previous
// one. It is meant for TestMain, where no *testing.T exists.
func Force() (restore func()) {
	previous := lipgloss.ColorProfile()
	lipgloss.SetColorProfile(termenv.TrueColor)
	return func() { lipgloss.SetColorProfile(previous) }
}

